public protocol EngineProtocol: AnyObject, Sendable {
    
    /**
     * Day 14: up to max ledger records as JSONL.
     */
    func drainLedgerJsonl(max: UInt32)  -> String
    
    /**
     * Bad bytes and backwards timestamps are counted/ignored, not thrown
     * through the platform callback.
     *
     * Vec<u8> is used because it is a supported owned UniFFI argument.
     */
    func ingest(tNs: UInt64, source: Source, bytes: Data)  -> CueDecision?
    
    /**
     * Day 12: the observer's latest verdict.
     */
    func lastOutcome()  -> CueOutcomeFfi?
    
    func onCueFailed(cueId: UInt32, reason: AudioFailure) 
    
    func onCuePlayed(cueId: UInt32, tOnsetNs: UInt64, tEndNs: UInt64, tCallbackNs: UInt64) 
    
    /**
     * Day 14: the ledger summary.
     */
    func reportCard()  -> ReportCard
    
    /**
     * Between sessions only. protocol_hash is the STUDY.md commit (Day 15).
     */
    func setMode(mode: Mode, seed: UInt64, protocolHash: String?) throws 
    
    func snapshot()  -> Snapshot
    
    func start(tNs: UInt64) 
    
    func tick(tNs: UInt64)  -> CueDecision?
    
}
