public enum Arm: Equatable, Hashable {
    
    case none
    case direct
    case autonomy
    case sham





}

#if compiler(>=6)
extension Arm: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeArm: FfiConverterRustBuffer {
    typealias SwiftType = Arm

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Arm {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .direct
        
        case 3: return .autonomy
        
