private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_vc_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_vc_ffi_checksum_func_encode_cue_played() != 52838) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_func_encode_load() != 48972) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_func_encode_ping() != 24046) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_func_encode_rider_input() != 47066) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_func_encode_start() != 61508) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_func_encode_stop() != 56211) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_func_scenarios() != 8848) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_drain_ledger_jsonl() != 54075) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_ingest() != 28414) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_last_outcome() != 28227) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_on_cue_failed() != 37387) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_on_cue_played() != 2344) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_report_card() != 10008) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_vc_ffi_checksum_method_engine_set_mode() != 1736) {
